let bunpoState={view:'list',id:null,q:'',category:'all',sub:'all',savedOnly:false,page:1};
let bunpoSaved=[];
let bunpoRomaji=false;
let bunpoCheckAnswer=null;
try{const saved=JSON.parse(localStorage.getItem('gaku-bunpo-saved'));if(Array.isArray(saved))bunpoSaved=[...new Set(saved.filter(id=>[...BUNPO_DATA,...BUNPO_N4_DATA].some(e=>e.id===id)))];bunpoRomaji=localStorage.getItem('gaku-bunpo-romaji')==='true'}catch{}
function getBunpoRoute(){return {...bunpoState}}
function resetBunpoRoute(){bunpoState={view:'list',id:null,q:'',category:'all',sub:'all',savedOnly:false,page:1};bunpoCheckAnswer=null}
function restoreBunpoRoute(state){resetBunpoRoute();if(!state)return;bunpoState.q=typeof state.q==='string'?state.q.slice(0,100):'';bunpoState.category=bunpoCategories().some(c=>c.id===state.category)?state.category:'all';bunpoState.sub=bunpoSubcategories(bunpoState.category).includes(state.sub)?state.sub:'all';bunpoState.page=Math.max(1,Math.floor(Number(state.page)||1));bunpoState.savedOnly=state.savedOnly===true;if(bunpoEntries().some(e=>e.id===state.id)){bunpoState.id=state.id;bunpoState.view=state.view==='detail'?'detail':'list'}}
function rememberBunpo(){if(page==='Bunpo')history.replaceState(appRoute(),'')}
function bunpoResults(){return findBunpo(bunpoState.q,bunpoState.category,bunpoState.sub,bunpoState.savedOnly,bunpoSaved,prefs.level)}
function bunpoCategory(id){return bunpoCategories().find(c=>c.id===id)}
function bunpoSearchChange(value){bunpoState.q=value.slice(0,100);bunpoState.page=1;refreshBunpoResults();rememberBunpo()}
function bunpoFilter(key,value){bunpoState[key]=value;bunpoState.page=1;if(key==='category')bunpoState.sub='all';rememberBunpo();render()}
function bunpoClear(){bunpoState.q='';bunpoState.category='all';bunpoState.sub='all';bunpoState.savedOnly=false;bunpoState.page=1;rememberBunpo();render();document.getElementById('bunpo-search').focus()}
function changeBunpoPage(n){bunpoState.page=n;refreshBunpoResults();rememberBunpo();document.getElementById('bunpo-results').scrollIntoView({block:'start',behavior:'instant'})}
function refreshBunpoResults(){const el=document.getElementById('bunpo-results');if(el)el.innerHTML=bunpoResultHTML()}
function openBunpo(id,replace=false){if(!bunpoEntries().some(e=>e.id===id))return;stopAudio();bunpoState.view='detail';bunpoState.id=id;bunpoCheckAnswer=null;if(replace)rememberBunpo();else pushRoute();updateScreen()}
function saveBunpo(){const id=bunpoState.id;if(!id)return;const next=bunpoSaved.includes(id)?bunpoSaved.filter(x=>x!==id):[...bunpoSaved,id];try{localStorage.setItem('gaku-bunpo-saved',JSON.stringify(next))}catch{toast('Materi belum bisa disimpan. Periksa ruang penyimpanan browser.');return}bunpoSaved=next;updateBunpoSaveButton();toast(next.includes(id)?'Materi disimpan di perangkat ini.':'Materi dihapus dari simpanan.')}
function updateBunpoSaveButton(){const b=document.getElementById('bunpo-save');if(!b)return;const saved=bunpoSaved.includes(bunpoState.id);b.setAttribute('aria-pressed',String(saved));b.innerHTML=(saved?'♥ Tersimpan':'♡ Simpan materi')}
function toggleBunpoRomaji(){bunpoRomaji=!bunpoRomaji;try{localStorage.setItem('gaku-bunpo-romaji',String(bunpoRomaji))}catch{}document.querySelector('.bunpo-detail')?.classList.toggle('show-romaji',bunpoRomaji);const b=document.getElementById('bunpo-romaji');b?.setAttribute('aria-pressed',String(bunpoRomaji));if(b)b.textContent=bunpoRomaji?'Romaji aktif':'Tampilkan romaji'}
function answerBunpoCheck(index){const e=bunpoEntries().find(e=>e.id===bunpoState.id);if(!e?.check||bunpoCheckAnswer!==null)return;bunpoCheckAnswer=index;const el=document.getElementById('bunpo-check');if(el)el.innerHTML=bunpoCheckHTML(e)}
function retryBunpoCheck(){bunpoCheckAnswer=null;const e=bunpoEntries().find(e=>e.id===bunpoState.id);document.getElementById('bunpo-check').innerHTML=bunpoCheckHTML(e)}
function bunpoStarterExample(x){return `<div class="bunpo-starter-example"><p lang="ja">${esc(x.jp)}</p><p lang="ja">${esc(x.kana)}</p><p class="bunpo-starter-romaji">${esc(bunpoExampleRomaji(x.kana))}</p><p>${esc(x.meaning)}</p></div>`}
function bunpoBeginnerHelp(){const guide=BUNPO_N5_STARTER;return `<div class="bunpo-beginner-help"><details class="bunpo-table-details bunpo-starter"><summary>Mulai dari nol: bekal sebelum belajar Bunpo</summary>${guide.sections.map(section=>`<section><h3>${esc(section.title)}</h3>${section.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${(section.examples||[]).map(bunpoStarterExample).join('')}</section>`).join('')}<div class="bunpo-starter-links"><span>Buka fondasi:</span>${['wa','wo','ni','de','verb-forms','i-adjective','na-adjective','te-sequence'].map(id=>{const e=BUNPO_DATA.find(x=>x.id===id);return `<button onclick="openBunpo('${id}')">${esc(e.title)}</button>`}).join('')}</div></details><details class="bunpo-table-details bunpo-starter"><summary>Panduan bentuk kata kerja: kamus, ます, ない, て, た</summary>${guide.verbGuide.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${guide.verbGuide.tables.map(t=>`<section><h3>${esc(t.title)}</h3><div class="bunpo-table-scroll" role="region" aria-label="${esc(t.title)}" tabindex="0"><table><thead><tr>${t.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`).join('')}<p>${esc(guide.verbGuide.closing)}</p></details></div>`}
function bunpoScreen(){if(bunpoState.view==='detail')return bunpoDetail();return title('Bunpo','Pahami polanya, lalu rangkai kalimatmu.')+`<div class="bunpo-library"><section class="bunpo-intro"><div><span class="bunpo-kicker">文法 · TATA BAHASA ${prefs.level}</span><h2>Kalimat kecil,<br>makna besar.</h2><p>${bunpoEntries().length} materi dalam ${bunpoCategories().length} kategori. Belajar satu pola, coba satu langkah.</p></div><div class="bunpo-book" aria-hidden="true"><span>文</span><small>あいう</small><i>✦</i></div></section>${prefs.level==='N5'?bunpoBeginnerHelp():''}<div class="bunpo-toolbar"><label for="bunpo-search" class="bunpo-search-label">Mau memahami pola apa?</label><div class="bunpo-searchbox"><span aria-hidden="true">⌕</span><input id="bunpo-search" type="search" autocomplete="off" maxlength="100" value="${esc(bunpoState.q)}" placeholder="Fungsi, kana, pola, atau romaji…" oninput="bunpoSearchChange(this.value)"></div><div class="bunpo-filters"><label>Kategori<select aria-label="Kategori Bunpo" onchange="bunpoFilter('category',this.value)"><option value="all">Semua kategori</option>${bunpoCategories().map(c=>`<option value="${c.id}" ${bunpoState.category===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Subkategori<select aria-label="Subkategori Bunpo" onchange="bunpoFilter('sub',this.value)"><option value="all">Semua subkategori</option>${bunpoSubcategories(bunpoState.category).map(s=>`<option value="${esc(s)}" ${bunpoState.sub===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="bunpo-filter-bottom"><span>Cari juga lewat fungsi, misalnya “ingin” atau “sebelum”.</span><button class="bunpo-saved-filter" aria-pressed="${bunpoState.savedOnly}" onclick="bunpoFilter('savedOnly',${!bunpoState.savedOnly})">${bunpoState.savedOnly?'♥':'♡'} Tersimpan</button></div></div><div id="bunpo-results" aria-live="polite" aria-atomic="false">${bunpoResultHTML()}</div></div>`}
function bunpoResultHTML(){const p=bunpoPageSlice(bunpoResults(),bunpoState.page);bunpoState.page=p.page;if(!p.total)return `<div class="bunpo-empty"><span>${bunpoState.savedOnly?'♡':'🌱'}</span><h2>${bunpoState.savedOnly&&!bunpoSaved.length?'Belum ada materi tersimpan':'Materinya belum ditemukan'}</h2><p>${bunpoState.savedOnly&&!bunpoSaved.length?'Buka materi, lalu ketuk “Simpan materi” agar mudah ditemukan lagi.':'Coba kata lain atau hapus filter. Kamu bisa mencari “te kudasai”, “たい”, atau “ingin”.'}</p><button class="primary" onclick="bunpoClear()">Lihat semua materi</button></div>`;const category=bunpoCategory(bunpoState.category);const start=(p.page-1)*BUNPO_PAGE_SIZE+1;let nums=[];for(let n=Math.max(1,p.page-2);n<=Math.min(p.totalPages,p.page+2);n++)nums.push(n);return `<div class="bunpo-result-head"><h2>${bunpoState.savedOnly?'Materi tersimpan':category?category.name:'Jelajahi pola kalimat'}</h2><span>${start}–${start+p.items.length-1} dari ${p.total}</span></div><div class="bunpo-grid">${p.items.map(e=>{const c=bunpoCategory(e.category);return `<button class="bunpo-card ${c.color}" onclick="openBunpo('${e.id}')" aria-label="Pelajari ${esc(e.title)}"><div class="bunpo-card-top"><span>${esc(e.subcategory)}</span><small>${bunpoSaved.includes(e.id)?'♥':String(e.order).padStart(2,'0')}</small></div><h3 lang="ja">${esc(e.title)}</h3><p>${esc(e.meaning)}</p><div class="bunpo-card-bottom"><span>${e.enrichment?'Pengayaan':esc(c.name)}</span><b aria-hidden="true">↗</b></div></button>`}).join('')}</div><nav class="bunpo-pagination" aria-label="Halaman Bunpo"><button aria-label="Bunpo halaman sebelumnya" ${p.page===1?'disabled':''} onclick="changeBunpoPage(${p.page-1})">‹</button>${p.page>3?'<span>…</span>':''}${nums.map(n=>`<button aria-label="Bunpo halaman ${n}" ${n===p.page?'class="current" aria-current="page"':''} onclick="changeBunpoPage(${n})">${n}</button>`).join('')}${p.page<p.totalPages-2?'<span>…</span>':''}<button aria-label="Bunpo halaman berikutnya" ${p.page===p.totalPages?'disabled':''} onclick="changeBunpoPage(${p.page+1})">›</button></nav><p class="bunpo-page-caption">Halaman ${p.page} / ${p.totalPages} · ${BUNPO_PAGE_SIZE} materi per halaman</p>`}
function bunpoDetail(){const e=bunpoEntries().find(e=>e.id===bunpoState.id);if(!e){bunpoState.view='list';return bunpoScreen()}const c=bunpoCategory(e.category),saved=bunpoSaved.includes(e.id);return `<article class="bunpo-detail ${c.color} ${bunpoRomaji?'show-romaji':''}"><header class="page-header"><button class="back" onclick="appBack()" aria-label="Kembali ke daftar Bunpo">‹</button><div><div class="eyebrow">${esc(c.name)} · ${esc(e.subcategory)}</div><h1>Bunpo <span>${e.enrichment?'Pengayaan':e.level}</span></h1></div></header><section class="bunpo-detail-hero"><span class="bunpo-kicker">POLA ${String(e.order).padStart(2,'0')}</span><h2 lang="ja">${esc(e.title)}</h2><p>${esc(e.meaning)}</p><span class="bunpo-hero-flower" aria-hidden="true">✿</span></section><div class="bunpo-detail-tools"><button id="bunpo-save" aria-pressed="${saved}" onclick="saveBunpo()">${saved?'♥ Tersimpan':'♡ Simpan materi'}</button><button id="bunpo-romaji" aria-pressed="${bunpoRomaji}" onclick="toggleBunpoRomaji()">${bunpoRomaji?'Romaji aktif':'Tampilkan romaji'}</button></div>${e.level==='N5'?bunpoBeginnerHelp():''}<section class="bunpo-section"><div class="bunpo-section-heading"><span>01</span><h2>Kapan dipakai?</h2></div><p class="bunpo-explanation">${esc(e.explanation)}</p></section><section class="bunpo-section"><div class="bunpo-section-heading"><span>02</span><h2>Susun polanya</h2></div><div class="bunpo-patterns">${e.patterns.map(p=>`<div>${esc(p)}</div>`).join('')}</div>${e.table?`<details class="bunpo-table-details"><summary>Lihat bentuk & perbedaannya</summary><div class="bunpo-table-scroll" role="region" aria-label="Tabel bentuk ${esc(e.title)}" tabindex="0"><table><thead><tr>${e.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${e.table.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`:''}<div class="bunpo-glossary"><strong>Kunci membaca pola</strong><p>${e.level==='N5'?esc('V = kata kerja (tindakan) · N = kata benda (orang, tempat, atau hal). Vて／Vた／Vない berarti bentuk kata kerja yang berakhir て／で, た／だ, atau ない. “Tanpa ます”: よみます → よみ. A dan B adalah bagian contoh; tanda + berarti sambungkan, bukan dibaca.'):esc('V = kata kerja · N = kata benda · Vて／Vた／Vない = bentuk kata kerja. “Tanpa ます” berarti buang akhiran ます, bukan membuang seluruh kata.')}</p>${e.level==='N4'?`<details><summary>Ingat kembali bekal N5</summary><p>Bentuk kamus: 読む. Bentuk biasa juga mencakup 読まない, 読んだ, dan 読まなかった; pilih sesuai maknanya, tanpa ます／です. Untuk N／sifat-na positif kini, bentuk biasanya memakai だ: 学生だ／静かだ.</p><p>Gol. I mengubah bunyi kana terakhir: む → ま／め, misalnya 読む → 読まれる／読めば. Gol. II membuang る: 食べる → 食べられる. Gol. III: する dan 来る. Tidak semua kata berakhiran る termasuk gol. II: 帰る termasuk gol. I.</p><p>Pangkal ます berarti buang ます saja: 読みます → 読み. Sifat-i misalnya 高い; sifat-na misalnya 静か. A dan B dalam penjelasan berarti bagian kalimat pertama dan berikutnya.</p></details>`:''}</div></section><section class="bunpo-section"><div class="bunpo-section-heading"><span>03</span><h2>Lihat dalam kalimat</h2></div><p class="bunpo-section-hint">Baca dulu, lalu buka artinya untuk mencocokkan.</p><div class="bunpo-examples">${e.examples.map((x,i)=>`<div class="bunpo-example"><span class="bunpo-example-num">CONTOH ${i+1}</span><p class="bunpo-japanese" lang="ja">${esc(x.jp)}</p><p class="bunpo-kana" lang="ja">${esc(x.kana)}</p><p class="bunpo-romaji">${esc(bunpoExampleRomaji(x.kana))}</p><details class="bunpo-translation"><summary>Lihat arti contoh ${i+1}</summary><p>${esc(x.meaning)}</p></details></div>`).join('')}</div></section><div class="bunpo-tip"><span aria-hidden="true">✦</span><div><h2>Catatan kecil</h2><p>${esc(e.note)}</p></div></div>${e.mistake?`<details class="bunpo-mistake"><summary>Yang sering tertukar</summary><div><span class="bunpo-wrong-label">Perlu diperbaiki</span><p lang="ja" class="bunpo-wrong">${esc(e.mistake.wrong)}</p><span class="bunpo-right-label">Gunakan ini</span><p lang="ja" class="bunpo-right">${esc(e.mistake.correct)}</p><p class="bunpo-why">${esc(e.mistake.why)}</p></div></details>`:''}${e.check?`<section class="bunpo-check-section"><span class="bunpo-kicker">COBA SEBENTAR</span><h2>Sudah mulai kebayang?</h2><p class="bunpo-section-hint">Latihan kecil untuk pola ini, tanpa skor.</p><div id="bunpo-check">${bunpoCheckHTML(e)}</div></section>`:''}<footer class="bunpo-detail-footer"><button class="kana-back-bottom" onclick="appBack()">‹ Kembali ke daftar Bunpo</button>${bunpoNextHTML(e)}</footer></article>`}
function bunpoCheckReading(kana){return kana?`<small class="bunpo-check-reading"><span lang="ja">Bacaan: ${esc(kana)}</span><span class="bunpo-romaji">${esc(bunpoExampleRomaji(kana))}</span></small>`:''}
function bunpoCheckHTML(e){const check=e.check;if(!check)return '';const answered=bunpoCheckAnswer!==null;const correct=bunpoCheckAnswer===check.answer;return `<p class="bunpo-check-prompt">${esc(check.prompt)}</p>${e.level==='N5'?bunpoCheckReading(check.promptKana):''}<div class="bunpo-check-choices">${check.options.map((o,i)=>`<button ${answered?'disabled':''} class="${answered&&(i===check.answer)?'correct':answered&&i===bunpoCheckAnswer?'wrong':''}" onclick="answerBunpoCheck(${i})"><span>${String.fromCharCode(65+i)}</span>${esc(o)}${e.level==='N5'?bunpoCheckReading(check.optionKana?.[i]):''}</button>`).join('')}</div><div class="bunpo-check-feedback" role="status">${answered?`<strong>${correct?'Tepat! ✦':'Belum tepat, yuk cocokkan.'}</strong><p>${esc(check.explanation)}</p><button onclick="retryBunpoCheck()">Coba lagi ↻</button>`:''}</div>`}
function bunpoNextHTML(e){const candidates=bunpoResults(),index=candidates.findIndex(x=>x.id===e.id),next=candidates[index+1];if(index<0||!next)return '';return `<button class="bunpo-next" onclick="openBunpo('${next.id}',true)"><small>Materi berikutnya</small><span>${esc(next.title)} <b>→</b></span></button>`}
